/// <summary>
/// This method will pass the selected Purchase orders to 
/// </summary>
public void clicked()
{
    FormControl                     formButtonControl = any2Object(this) as FormControl;
    FormDataSource                  wMSArrivalOverviewTmpDS = formButtonControl.formRun().dataSource(tableStr(WMSArrivalOverviewTmp));
    Map                             mapPurchTable = new Map(typeName2Type(extendedTypeStr(RecId)), Types::Record);
    PurchFormLetter_ReceiptsList    purchFormLetter_ReceiptsList;
    purchTable                      purchTable;
    InventTransRefId                PrevInventTransRefId;

    next clicked();

    wMSArrivalOverviewTmpDS.filter(fieldNum(WMSArrivalOverviewTmp, Selected), queryValue(NoYes::Yes));
    wMSArrivalOverviewTmpDS.first();

    WMSArrivalOverviewTmp WMSArrivalOverviewTmp = wMSArrivalOverviewTmpDS.cursor();

    while (wMSArrivalOverviewTmp && WMSArrivalOverviewTmp.InventTransRefId != PrevInventTransRefId)
    {
        if (wMSArrivalOverviewTmp.InventTransType != InventTransType::Purch)
        {
            throw Error("@MET:METTypeValidate");
        }

        Info(WMSArrivalOverviewTmp.InventTransRefId);
        PrevInventTransRefId = WMSArrivalOverviewTmp.InventTransRefId;
        purchTable = PurchTable::find(WMSArrivalOverviewTmp.InventTransRefId);
        mapPurchTable.insert(purchTable.RecId, purchTable);

        wMSArrivalOverviewTmpDS.next();
        WMSArrivalOverviewTmp = wMSArrivalOverviewTmpDS.cursor();
    }
    wMSArrivalOverviewTmpDS.removeFilter();

    purchFormLetter_ReceiptsList = PurchFormLetter::construct(DocumentStatus::ReceiptsList);
    purchFormLetter_ReceiptsList.parmDataSourceRecordsPacked(mapPurchTable.pack());
    purchFormLetter_ReceiptsList.chooseLines();

    if (purchFormLetter_ReceiptsList.prompt())
    {
        purchFormLetter_ReceiptsList.run();
    }
}
